    swapMode: zod_1.z.enum(['ExactIn', 'ExactOut']).optional().describe('Swap mode (default: ExactIn)'),
    onlyDirectRoutes: zod_1.z.boolean().optional().describe('Restrict to single-hop routes for lower latency'),
